-- ============================================================
-- Carga AdaptAI — escolas estaduais de Belém e Ananindeua (lista SEDUC)
-- ============================================================
-- Lista "DREs e Escolas" (SEDUC-PA) trazida pela Lia em 16/10/2026:
-- DRE Belém 01 a 10 e DRE Ananindeua 01 a 05 (298 escolas).
-- Entram no funil do AdaptAI na etapa Lista, como "Escola pública estadual",
-- com origem "lista", responsável = Lia (se houver exatamente uma pessoa
-- ativa com o primeiro nome Lia; senão ficam sem responsável, na fila).
-- O telefone é o ramal da lista: confirmar telefone direto e e-mail.
-- Não duplica: escola com o mesmo nome (sem diferenciar maiúsculas) é pulada.
-- ============================================================

WITH lia AS (
  SELECT CASE WHEN count(*) = 1 THEN min(id::text)::uuid END AS id
    FROM pessoas_acesso
   WHERE ativo AND lower(split_part(trim(nome), ' ', 1)) = 'lia'
),
hoje AS (SELECT (now() AT TIME ZONE 'America/Sao_Paulo')::date AS d),
dados (nome, etapas_ensino, bairro, rota, endereco, cidade, telefone, dre) AS (VALUES
