novas AS (
  INSERT INTO adapt_escolas (protocolo, nome, tipo, trilha, etapas_ensino, bairro, rota, endereco, cidade, uf, telefone,
                             fonte_dados, dados_confirmados, etapa, etapa_desde, marcos, origem, dono_id, criado_por_id, notas)
  SELECT 'AD-' || to_char(h.d, 'YYYYMMDD') || '-' || upper(substr(md5(random()::text || x.nome), 1, 5)),
         x.nome, 'publica_estadual', 'escola', x.etapas_ensino, x.bairro, x.rota, x.endereco, x.cidade, 'PA', x.telefone,
         'Lista SEDUC DREs e Escolas (trazida pela Lia, 16/10/2026) — confirmar por telefone', FALSE,
         'lista', h.d, jsonb_build_object('lista', h.d::text), 'lista', l.id, l.id,
         x.dre || '. Telefone da lista é o ramal SEDUC: confirmar telefone direto, e-mail e quem é a gestão da escola.'
    FROM dados x CROSS JOIN hoje h CROSS JOIN lia l
   WHERE NOT EXISTS (SELECT 1 FROM adapt_escolas e WHERE lower(e.nome) = lower(x.nome))
  RETURNING id, criado_por_id
)
INSERT INTO adapt_movimentos (escola_id, de_etapa, para_etapa, pessoa_id, justificativa)
SELECT n.id, NULL, 'lista', n.criado_por_id, 'carga da lista SEDUC (Belém e Ananindeua)'
  FROM novas n;
